#!/bin/bash
#
# Generates the C++ bindings in ../v11 for IEEE 2030.5-2018 with the
# CSIP-AUS v1.1 extensions (the schema CSIP-AUS v1.1a and v1.2 share).
#
#   generate.sh [SEP_XSD]
#
# SEP_XSD is the IEEE 2030.5-2018 sep.xsd (schema version 2.1.0), from
# https://standards.ieee.org/content/dam/ieee-standards/standards/web/download/2030.5-2018_downloads.zip
# It defaults to the copy under specs/. IEEE's terms do not allow it to be
# redistributed, so it is not in the repository; the bindings are generated
# without its documentation text.
#
# csipaus-core.xsd and csipaus-ext.xsd are CSIP-AUS v1.1 as published at
# https://csipaus.org/ns. merge_redefines.py applies csipaus-core.xsd's
# redefinitions to sep.xsd, since the XSD compiler cannot, and
# complete_includes.py adds includes the compiler leaves out.
#
# Needs xsdcxx (CodeSynthesis XSD 4.0.0, the version vendored under
# vendor/xsd-4.0.0) and python3, which the codegen image has. From the
# repository root:
#
#   docker build --target codegen -t grid-services-codegen .
#   docker run --rm -v "$PWD":/src -w /src grid-services-codegen \
#       vendor/csipaussd/csipaussd/schema/generate.sh

set -euo pipefail

schema_dir=$(cd "$(dirname "$0")" && pwd)
repo=$(cd "$schema_dir/../../../.." && pwd)
sep_xsd=${1:-$repo/specs/ieee-2030.5-2018/downloads/sep.xsd}
out=$schema_dir/../v11

if [[ ! -f $sep_xsd ]]; then
  echo "IEEE 2030.5-2018 sep.xsd not found at $sep_xsd" >&2
  exit 1
fi
if ! grep -q 'version="2.1.0"' "$sep_xsd"; then
  echo "$sep_xsd is not the 2030.5-2018 schema (version 2.1.0)" >&2
  exit 1
fi

work=$(mktemp -d)
trap 'rm -rf "$work"' EXIT

python3 "$schema_dir/merge_redefines.py" \
  "$sep_xsd" "$schema_dir/csipaus-core.xsd" "$work/sep.xsd"
cp "$schema_dir/csipaus-ext.xsd" "$work/"
# Only names the output of --generate-xml-schema below.
touch "$work/xml-schema.xsd"

# The documents a CSIP-AUS client exchanges with a utility server, which
# get parse and serialize functions. Add one here to read or send it whole.
documents=(
  # Discovery and registration
  DeviceCapability Time EndDeviceList EndDevice Registration
  ConnectionPoint
  # Controls
  FunctionSetAssignmentsList FunctionSetAssignments
  DERProgramList DERProgram DERControlList DERControl DefaultDERControl
  DERControlResponse
  # The site's DER
  DERList DER DERCapability DERSettings DERStatus DERAvailability
  # Telemetry
  MirrorUsagePointList MirrorUsagePoint
  MirrorMeterReadingList MirrorMeterReading
  # Server errors
  Error
)
roots=()
for document in "${documents[@]}"; do
  roots+=(--root-element "$document")
done

rm -rf "$out"
mkdir -p "$out"

# The XML Schema built-ins go in csipaus::xml_schema, apart from the
# xml_schema namespace liboadr's bindings define.
common=(
  --std c++11
  --namespace-map http://www.w3.org/2001/XMLSchema=csipaus::xml_schema
  --generate-serialization
  --generate-comparison
  --prologue "// Generated by vendor/csipaussd/csipaussd/schema/generate.sh."
)

# The XML Schema built-in types, once, instead of in every header.
xsdcxx cxx-tree "${common[@]}" \
  --generate-xml-schema \
  --output-dir "$out" \
  "$work/xml-schema.xsd"

xsdcxx cxx-tree "${common[@]}" \
  --extern-xml-schema xml-schema.xsd \
  --file-per-type \
  "${roots[@]}" \
  --namespace-map urn:ieee:std:2030.5:ns=csipaus::sep \
  --namespace-map https://csipaus.org/ns=csipaus::ext \
  --output-dir "$out" \
  "$work/sep.xsd" "$work/csipaus-ext.xsd"

python3 "$schema_dir/complete_includes.py" "$out"

echo "Generated $(ls "$out" | wc -l) files in $out"
